<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { getAdminStatisticsApi, listAdminRescuesApi, listAdminUsersApi, listAdminVolunteerApplicationsApi, reviewRescueApi, reviewVolunteerApplicationApi, updateUserStatusApi, confirmRescueApi } from '../api/admin'; import type { User } from '../types/api'; import type { AdminStatistics, RescueOrder, VolunteerApplication } from '../types/business'
const tab=ref('overview');const stats=ref<AdminStatistics|null>(null);const users=ref<User[]>([]);const applications=ref<VolunteerApplication[]>([]);const rescues=ref<RescueOrder[]>([]);const query=reactive({keyword:'',status:'',page:1,size:20})
async function loadStats(){stats.value=(await getAdminStatisticsApi()).data.data}async function loadUsers(){users.value=(await listAdminUsersApi(query)).data.data.records}async function loadApplications(){applications.value=(await listAdminVolunteerApplicationsApi({page:1,size:20})).data.data.records}async function loadRescues(){rescues.value=(await listAdminRescuesApi({page:1,size:20})).data.data.records}
async function toggleUser(user:User){const status=user.status==='ACTIVE'?'DISABLED':'ACTIVE';await ElMessageBox.confirm(`确认将账号 ${user.username} 设置为 ${status} 吗？`,'账号状态');await updateUserStatusApi(user.id,status);ElMessage.success('账号状态已更新');loadUsers()}
async function reviewVolunteer(id:number,decision:string){const {value}=await ElMessageBox.prompt('请输入审核意见','志愿者申请审核',{inputValue:decision==='APPROVE'?'资料符合志愿者要求':'资料暂不符合要求'});await reviewVolunteerApplicationApi(id,decision,value);ElMessage.success('审核完成');loadApplications()}
async function reviewRescue(order:RescueOrder,decision:string){const {value}=await ElMessageBox.prompt('请输入审核意见','救助工单审核',{inputValue:decision==='APPROVE'?'情况属实，同意公开':'信息不足，暂不公开'});await reviewRescueApi(order.id,decision,value);ElMessage.success('工单审核完成');loadRescues();loadStats()}
async function confirm(order:RescueOrder,decision:string){const {value}=await ElMessageBox.prompt('请输入验收意见','处理结果验收',{inputValue:decision==='CONFIRM'?'处理结果符合要求':'请志愿者补充处理反馈'});await confirmRescueApi(order.id,decision,value);ElMessage.success('验收完成');loadRescues();loadStats()}
onMounted(()=>{loadStats();loadUsers();loadApplications();loadRescues()})
</script>
<template><section class="admin-page"><aside class="admin-sidebar"><div class="admin-title"><span class="brand-mark">蓝</span><div><strong>蓝境管理台</strong><small>ADMIN CONSOLE</small></div></div><button :class="{active:tab==='overview'}" @click="tab='overview'">数据概览</button><button :class="{active:tab==='users'}" @click="tab='users'">用户管理</button><button :class="{active:tab==='volunteers'}" @click="tab='volunteers'">志愿者审核</button><button :class="{active:tab==='rescues'}" @click="tab='rescues'">救助工单</button><RouterLink to="/">返回用户端</RouterLink></aside><main class="admin-content"><header><div><p>MANAGEMENT SYSTEM</p><h1>{{ tab==='overview'?'数据概览':tab==='users'?'用户管理':tab==='volunteers'?'志愿者申请':'救助工单管理' }}</h1></div></header><template v-if="tab==='overview'&&stats"><div class="stat-grid"><article><small>正常用户</small><strong>{{stats.activeUserCount}}</strong></article><article><small>识别次数</small><strong>{{stats.detectionCount}}</strong></article><article><small>救助工单</small><strong>{{stats.rescueOrderCount}}</strong></article><article><small>已完成救助</small><strong>{{stats.completedRescueOrderCount}}</strong></article></div><div class="chart-grid"><article><h3>识别状态分布</h3><div v-for="item in stats.detectionsByStatus" :key="item.label" class="bar-row"><span>{{item.label}}</span><div><i :style="{width:`${Math.min(item.count*10,100)}%`}"></i></div><strong>{{item.count}}</strong></div></article><article><h3>救助工单状态</h3><div v-for="item in stats.rescueOrdersByStatus" :key="item.label" class="bar-row"><span>{{item.label}}</span><div><i :style="{width:`${Math.min(item.count*10,100)}%`}"></i></div><strong>{{item.count}}</strong></div></article></div></template><template v-if="tab==='users'"><div class="admin-filter"><el-input v-model="query.keyword" placeholder="搜索用户名、昵称、邮箱或手机" clearable/><el-select v-model="query.status" clearable placeholder="账号状态"><el-option label="正常" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select><el-button type="primary" @click="loadUsers">查询</el-button></div><el-table :data="users" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="username" label="用户名"/><el-table-column prop="nickname" label="昵称"/><el-table-column prop="email" label="邮箱"/><el-table-column prop="status" label="状态"><template #default="scope"><el-tag :type="scope.row.status==='ACTIVE'?'success':'danger'">{{scope.row.status}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button link type="primary" @click="toggleUser(scope.row)">{{scope.row.status==='ACTIVE'?'停用':'启用'}}</el-button></template></el-table-column></el-table></template><template v-if="tab==='volunteers'"><el-table :data="applications" stripe><el-table-column prop="realName" label="姓名"/><el-table-column prop="phone" label="电话"/><el-table-column prop="region" label="地区"/><el-table-column prop="skills" label="技能"/><el-table-column prop="reason" label="申请理由" min-width="180"/><el-table-column prop="status" label="状态"/><el-table-column label="审核" width="150"><template #default="scope"><template v-if="scope.row.status==='PENDING'"><el-button link type="success" @click="reviewVolunteer(scope.row.id,'APPROVE')">通过</el-button><el-button link type="danger" @click="reviewVolunteer(scope.row.id,'REJECT')">拒绝</el-button></template><span v-else>{{scope.row.reviewComment}}</span></template></el-table-column></el-table></template><template v-if="tab==='rescues'"><el-table :data="rescues" stripe><el-table-column prop="title" label="标题" min-width="180"/><el-table-column prop="issueType" label="类型"/><el-table-column prop="locationText" label="位置"/><el-table-column prop="status" label="状态"/><el-table-column prop="description" label="描述" min-width="220"/><el-table-column label="操作" width="190"><template #default="scope"><template v-if="scope.row.status==='PENDING_REVIEW'"><el-button link type="success" @click="reviewRescue(scope.row,'APPROVE')">公开</el-button><el-button link type="danger" @click="reviewRescue(scope.row,'REJECT')">拒绝</el-button></template><template v-else-if="scope.row.status==='COMPLETION_PENDING'"><el-button link type="success" @click="confirm(scope.row,'CONFIRM')">验收</el-button><el-button link type="danger" @click="confirm(scope.row,'REJECT')">退回</el-button></template><span v-else>{{scope.row.reviewComment||scope.row.confirmComment||'流程处理中'}}</span></template></el-table-column></el-table></template></main></section></template>
